39	 * advice may never be consulted at all and every refusal below would answer {@code 500}
40	 * instead — as a {@code 500} that looks exactly like a genuine one.
41	 */
42	@Order(Ordered.HIGHEST_PRECEDENCE)
43	@RestControllerAdvice(assignableTypes = TransferController.class)
44	class TransferRefusalAdvice {
45	
46		private static final String SELF_TRANSFER_DETAIL =
47				"A Transfer must move money between two different Accounts.";
48	
49		private static final String UNKNOWN_ACCOUNT_DETAIL = "No Account has that identifier.";
50	
51		private static final String INSUFFICIENT_FUNDS_DETAIL =
52				"The source Account's Available Balance does not cover this Transfer.";
53	
54		private static final String CROSS_CURRENCY_DETAIL =
55				"This service cannot yet convert between the two Accounts' Currencies.";
56	
57		@ExceptionHandler
58		ProblemDetail handleSelfTransfer(SelfTransferNotAllowedException refusal, HttpServletRequest request) {
59			ProblemDetail problem = refusalOf(ProblemType.SELF_TRANSFER, SELF_TRANSFER_DETAIL, request);
60			problem.setProperty("accountId", refusal.getAccountId());
61			return problem;
62		}
63	
64		@ExceptionHandler
65		ProblemDetail handleUnknownAccount(UnknownAccountException refusal, HttpServletRequest request) {
66			ProblemDetail problem = refusalOf(ProblemType.UNKNOWN_ACCOUNT, UNKNOWN_ACCOUNT_DETAIL, request);
67			problem.setProperty("accountId", refusal.getAccountId());
68			return problem;
69		}
70	
71		/**
72		 * Both figures that were compared, and the Currency they were compared in — which is one
73		 * member rather than two because an Available Balance and the amount tested against it
74		 * cannot be denominated differently and still have been compared.
75		 */
76		@ExceptionHandler
77		ProblemDetail handleInsufficientFunds(InsufficientFundsException refusal, HttpServletRequest request) {
78			ProblemDetail problem = refusalOf(ProblemType.INSUFFICIENT_FUNDS, INSUFFICIENT_FUNDS_DETAIL, request);
79			problem.setProperty("availableBalanceMinorUnits", refusal.getAvailableBalance().minorUnits());
80			problem.setProperty("requestedAmountMinorUnits", refusal.getRequestedAmount().minorUnits());
81			problem.setProperty("currency", refusal.getAvailableBalance().currency());
82			return problem;
83		}
84	
85		@ExceptionHandler
86		ProblemDetail handleCrossCurrencyTransfer(CrossCurrencyTransferNotSupportedException refusal,
87				HttpServletRequest request) {
88			ProblemDetail problem = refusalOf(ProblemType.CROSS_CURRENCY_UNSUPPORTED, CROSS_CURRENCY_DETAIL, request);
89			problem.setProperty("sourceCurrency", refusal.getSourceCurrency());
90			problem.setProperty("destinationCurrency", refusal.getDestinationCurrency());
91			return problem;
92		}
93	
94		/**
95		 * The parts every refusal shares. {@code instance} is set by hand because the base class
96		 * that would otherwise do it is the one this advice deliberately is not, and a document
97		 * missing it would be the one shape a client could not treat like the others.
98		 */
99		private static ProblemDetail refusalOf(ProblemType type, String detail, HttpServletRequest request) {
100			ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.UNPROCESSABLE_ENTITY, detail);
101			problem.setType(type.uri());
102			problem.setInstance(URI.create(request.getRequestURI()));
103			return problem;
104		}
105	}

